//! Builds the vendored Codec2 speech codec (codec2/README.md): codebooks from their text
//! tables, then the C sources with `cc`.

use std::fmt::Write as _;
use std::path::{Path, PathBuf};

/// Generated file, table name, text tables (codec2's src/CMakeLists.txt).
const CODEBOOKS: &[(&str, &str, &[&str])] = &[
    (
        "codebook.c",
        "lsp_cb",
        &[
            "lsp1", "lsp2", "lsp3", "lsp4", "lsp5", "lsp6", "lsp7", "lsp8", "lsp9", "lsp10",
        ],
    ),
    (
        "codebookd.c",
        "lsp_cbd",
        &[
            "dlsp1", "dlsp2", "dlsp3", "dlsp4", "dlsp5", "dlsp6", "dlsp7", "dlsp8", "dlsp9",
            "dlsp10",
        ],
    ),
    (
        "codebookjmv.c",
        "lsp_cbjmv",
        &["lspjmv1", "lspjmv2", "lspjmv3"],
    ),
    ("codebookge.c", "ge_cb", &["gecb"]),
    (
        "codebooknewamp1.c",
        "newamp1vq_cb",
        &["train_120_1", "train_120_2"],
    ),
    (
        "codebooknewamp1_energy.c",
        "newamp1_energy_cb",
        &["newamp1_energy_q"],
    ),
];

const SOURCES: &[&str] = &[
    "lpc",
    "nlp",
    "postfilter",
    "sine",
    "codec2",
    "codec2_fft",
    "kiss_fft",
    "kiss_fftr",
    "interp",
    "lsp",
    "mbest",
    "newamp1",
    "phase",
    "quantise",
    "pack",
];

fn main() {
    let root =
        PathBuf::from(std::env::var("CARGO_MANIFEST_DIR").expect("cargo sets it")).join("codec2");
    let out = PathBuf::from(std::env::var("OUT_DIR").expect("cargo sets it"));
    println!("cargo:rerun-if-changed=codec2");

    std::fs::create_dir_all(out.join("codec2")).expect("out dir");
    std::fs::write(
        out.join("codec2/version.h"),
        "#define CODEC2_VERSION_MAJOR 1\n#define CODEC2_VERSION_MINOR 2\n\
         #define CODEC2_VERSION_PATCH 0\n#define CODEC2_VERSION \"1.2.0\"\n",
    )
    .expect("version.h");

    let mut build = cc::Build::new();
    for (file, name, tables) in CODEBOOKS {
        let c = codebook(&root.join("codebook"), name, tables);
        let path = out.join(file);
        std::fs::write(&path, c).expect("codebook");
        build.file(path);
    }
    for s in SOURCES {
        build.file(root.join("src").join(format!("{s}.c")));
    }
    build
        .include(root.join("src"))
        .include(&out)
        .opt_level(2)
        .warnings(false)
        .flag_if_supported("-fno-strict-aliasing")
        .compile("codec2");
}

/// The C that codec2's `generate_codebook` prints for these tables.
fn codebook(dir: &Path, name: &str, tables: &[&str]) -> String {
    let mut c = String::from(
        "/* Generated by lc-media/build.rs from codec2's codebook tables (LGPL 2.1). */\n\n\
         #include \"defines.h\"\n\n",
    );
    let mut dims = Vec::new();
    for (i, t) in tables.iter().enumerate() {
        let text = std::fs::read_to_string(dir.join(format!("{t}.txt"))).expect("codebook table");
        let numbers: Vec<f64> = text
            .lines()
            .map(|l| l.split('#').next().unwrap_or(""))
            .flat_map(str::split_whitespace)
            .map(|n| n.parse().expect("a number"))
            .collect();
        let (k, m) = (numbers[0] as usize, numbers[1] as usize);
        let values = &numbers[2..2 + k * m];
        let _ = writeln!(c, "  /* {t}.txt */\nstatic float codes{i}[] = {{");
        for (j, v) in values.iter().enumerate() {
            let _ = write!(c, "  {}", g(f64::from(*v as f32)));
            if j + 1 < values.len() {
                c.push(',');
            }
            if (j + 1) % k == 0 {
                c.push('\n');
            }
        }
        c.push_str("};\n");
        dims.push((t, k, m));
    }
    let _ = writeln!(c, "\nconst struct lsp_codebook {name}[] = {{");
    for (i, (t, k, m)) in dims.iter().enumerate() {
        let log2m = (*m as f64).log2().round() as u32;
        let _ = writeln!(
            c,
            "  /* {t}.txt */\n  {{\n    {k},\n    {log2m},\n    {m},\n    codes{i}\n  }},"
        );
    }
    c.push_str("  { 0, 0, 0, 0 }\n};\n");
    c
}

/// C's `%g`: six significant digits, fixed or scientific, trailing zeros removed.
fn g(x: f64) -> String {
    if x == 0.0 {
        return if x.is_sign_negative() {
            "-0".into()
        } else {
            "0".into()
        };
    }
    let sci = format!("{x:.5e}");
    let (mant, exp) = sci.split_once('e').expect("exponent");
    let exp: i32 = exp.parse().expect("exponent");
    let trim = |s: String| {
        if s.contains('.') {
            s.trim_end_matches('0').trim_end_matches('.').to_string()
        } else {
            s
        }
    };
    if (-4..6).contains(&exp) {
        trim(format!("{:.*}", (5 - exp) as usize, x))
    } else {
        let m = trim(mant.to_string());
        format!("{m}e{}{:02}", if exp < 0 { '-' } else { '+' }, exp.abs())
    }
}
